    {"type": "function", "function": {"name": "edit_file", "description": "Edit a file by exact text replacement. Each edit has oldText (text to find) and newText (replacement). oldText must be unique in the file. Merge nearby changes into one edit.", "parameters": {"type": "object", "properties": {"path": {"type": "string", "description": "Path to file"}, "edits": {"type": "array", "items": {"type": "object", "properties": {"oldText": {"type": "string", "description": "Exact text to replace"}, "newText": {"type": "string", "description": "Replacement text"}, "edit_type": {"type": "string", "description": "'replace' (default), 'insert_after', or 'insert_before'"}}, "required": ["oldText", "newText"]}, "description": "List of edits"}}, "required": ["path", "edits"]}}},
