    {"type": "function", "function": {"name": "memory_core", "description": "Manage persistent core memory. action: 'read', 'add', 'replace', 'remove'.", "parameters": {"type": "object", "properties": {"action": {"type": "string", "description": "'read', 'add', 'replace', or 'remove'"}, "content": {"type": "string", "description": "Content for add/replace"}, "line": {"type": "integer", "description": "Line number to remove (1-indexed)"}}, "required": ["action"]}}},
